def run(context):
    # Sample calculation of trend strength
    data = context.get_data('market.equity_eod', symbol=context.inputs['symbol'])
    trend_strength = data['close'].pct_change().mean()
    return {'trend_strength': trend_strength}

def run(context):
    thresholds = context.get('thresholds', {})
    fresher_than = {}
    alerts = []
    for key, date in context.items():
        if date < thresholds.get(key, ''):  # assuming context has dates as strings
            alerts.append(f'{key} data is stale.')
        else:
            fresher_than[key] = date
    return {'freshness_status': fresher_than, 'alerts': alerts}

